const cityPaintFragments=new Map<string,string>();
/** The Berlin baseline and F009 owner both contain the identical legacy Rotes helpers. */
function uniqueBerlinRotesMain(source:string):string{
 for(const name of ['rr500Box','rr500Arch','rr500Brick','rr500Window','ppRotesRathausFull500','ppRotesRoofExtended500']){
  const expression=new RegExp('\\b(?:float|vec3)\\s+'+name+'\\s*\\([^{};]*\\)\\s*\\{','g');const ranges:{start:number;end:number;body:string}[]=[];let match:RegExpExecArray|null;
  while((match=expression.exec(source))!==null){let end=expression.lastIndex,depth=1;while(end<source.length&&depth){if(source[end]==='{')depth++;else if(source[end]==='}')depth--;end++;}if(depth)throw Error('Unclosed Berlin Rotes definition '+name);ranges.push({start:match.index,end,body:source.slice(match.index,end).replace(/\s+/g,'')});expression.lastIndex=end;}
  if(ranges.length<2)continue;
  if(ranges.some(r=>r.body!==ranges[0].body))throw Error('Conflicting Berlin Rotes definitions '+name);
  for(const r of ranges.slice(1).reverse())source=source.slice(0,r.start)+source.slice(r.end);
 }
 return source;
}

export function facadePaintFragmentForCity(city:string):string {
 const extra=PROGRESSIVE_CITY_SOURCE_FULL_SHA===PROGRESSIVE_FEATURE_SHA?PROGRESSIVE_CITY_EXTRA_GLSL[city]:undefined;
 if(extra===undefined)return scopeInfillPaint(FACADE_PAINT_FRAGMENT_GLSL,city);
 let fragment=cityPaintFragments.get(city);
 if(fragment===undefined){fragment=scopeInfillPaint(makeFacadePaintFragment(PROGRESSIVE_CITY_BASELINE_GLSL+extra,'progressiveFeatureDispatchCity',city),city);if(city==='berlin')fragment=uniqueBerlinRotesMain(fragment);cityPaintFragments.set(city,fragment);}
 return fragment;
}

